CREATE OR REPLACE FUNCTION app.preview_global_component(p_site_id uuid, p_kind global_element_kind, p_content jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NOT app.has_site_access(p_site_id) THEN
